def ppo_loss(new_logps, old_logps, advantages, clip_ratio=0.2):
    new_logps, old_logps, advantages = [_array(v) for v in (new_logps,old_logps,advantages)]
    clip_ratio = _scalar(clip_ratio)
    if new_logps.ndim != 1 or new_logps.size == 0 or old_logps.shape != new_logps.shape or advantages.shape != new_logps.shape:
        raise ValueError("Use matching nonempty vectors")
    delta = new_logps-old_logps
    if np.any(new_logps > 0) or np.any(old_logps > 0) or np.any(np.abs(delta) > 60) or not 0 <= clip_ratio < 1:
        raise ValueError("Invalid log probabilities or clipping interval")
    ratios = np.exp(delta)
    clipped = np.clip(ratios,1-clip_ratio,1+clip_ratio)
    return float(-np.minimum(ratios*advantages,clipped*advantages).mean())
